### Example: Fixing a flaky e2e test with proper async handling

```typescript
// foreman-tick84-e2e.test.ts
import { describe, it, expect, beforeAll, afterAll } from 'vitest';

// Hypothetical system under test
interface TickResult {
  id: string;
  status: 'pending' | 'completed' | 'failed';
  output: string;
  timestamp: number;
}

class ForemanService {
  async submitTick(task: string): Promise<string> {
    const response = await fetch('/api/foreman/tick', {
      method: 'POST',
      body: JSON.stringify({ task }),
      headers: { 'Content-Type': 'application/json' }
    });
    if (!response.ok) throw new Error(`Submit failed: ${response.status}`);
    const { id } = await response.json();
    return id;
  }

  async getTickResult(id: string): Promise<TickResult> {
    const response = await fetch(`/api/foreman/tick/${id}`);
    if (!response.ok) throw new Error(`Fetch failed: ${response.status}`);
    return response.json();
  }
}

// The fix: add proper polling with timeout and retry logic
async function waitForCompletion(
  foreman: ForemanService,
  tickId: string,
  timeoutMs: number = 30_000,
  pollIntervalMs: number = 500
): Promise<TickResult> {
  const deadline = Date.now() + timeoutMs;

  while (Date.now() < deadline) {
    const result = await foreman.getTickResult(tickId);
    if (result.status === 'completed') return result;
    if (result.status === 'failed') {
      throw new Error(`Tick ${tickId} failed: ${result.output}`);
    }
    await new Promise(resolve => setTimeout(resolve, pollIntervalMs));
  }

  throw new Error(`Tick ${tickId} timed out after ${timeoutMs}ms`);
}

describe('foreman-tick84-e2e', () => {
  let foreman: ForemanService;

  beforeAll(() => {
    foreman = new ForemanService();
    // Bootstrap: ensure test environment is clean
  });

  afterAll(() => {
    // Teardown: clean up test resources
  });

  it('completes a tick from submission to completion', async () => {
    // Submit a tick
    const tickId = await foreman.submitTick('e2e-test-task-84');
    expect(tickId).toBeDefined();

    // Wait for completion with proper polling
    const result = await waitForCompletion(foreman, tickId);

    // Assert the result
    expect(result.status).toBe('completed');
    expect(result.output).toContain('success');
    expect(result.timestamp).toBeGreaterThan(0);
  });

  it('handles concurrent tick submissions', async () => {
    const tasks = Array.from({ length: 5 }, (_, i) => 
      foreman.submitTick(`concurrent-task-${i}`)
    );
    const tickIds = await Promise.all(tasks);
    expect(tickIds).toHaveLength(5);

    const results = await Promise.all(
      tickIds.map(id => waitForCompletion(foreman, id))
    );
    results.forEach(r => expect(r.status).toBe('completed'));
  });

  it('properly reports errors for invalid tasks', async () => {
    await expect(
      foreman.submitTick('')
    ).rejects.toThrow('Submit failed');
  });

  it('times out on stuck ticks', async () => {
    const tickId = await foreman.submitTick('stuck-task');
    await expect(
      waitForCompletion(foreman, tickId, 5_000)
    ).rejects.toThrow('timed out');
  });
});
